What I did was add a useState in the SidebarContext and then use it in the sidebar-rendered. Obviously, before each change in the form, I save it with `setFormData`

```
 const { nodeRender, setNodeRender, formData } = useContext(SidebarContext);
 const handleSave = () => {
        nodeRender?.form?.setValueIn("inputsValues", formData)
        handleClose()
 }
```

This is how the `SidebarContext.ts` looks like:
```
export const SidebarContext = React.createContext<{
    visible: boolean;
    nodeRender?: NodeRenderReturnType;
    formData?: Record<string, FlowValueSchema>;
    setNodeRender: (node: NodeRenderReturnType | undefined) => void;
    setFormData: (formData: Record<string, FlowValueSchema> | undefined) => void
}>({
    visible: false,
    setNodeRender: () => { },
    setFormData: () => { },
});
```

Update SidebarProvider like this：

```
export function SidebarProvider({ children }: { children: React.ReactNode }) {
  const [sidebarValue, setSideBarValue] = useState<any | undefined>();
  const setNodeRender = (nodeRender) {
    if (!nodeRender) {
      setSideBarValue(undefined)
    } else {
      setSideBarValue({
        visible: !!nodeRender,
        nodeRender?: nodeRender,
        formData: nodeRender.form.values,
        setFormData: (formData: Record<string, FlowValueSchema> | undefined) => {
          nodeRender.form.setValue('inputsValues', formData)
        }
      })
    }
  }
  return (
    <SidebarContext.Provider value={{ ...sidebarValue, setNodeRender}}>
      {children}
    </SidebarContext.Provider>
  );
}


```

